content:
root = Stack([title, mainCard, stepsTitle, cascadeSteps])
title = TextContent("Failure Cascade: auth-db Outage", "large-heavy")
mainCard = Card([graphHeader, graph])
graphHeader = CardHeader("Dependency Graph", "Visualizing failure propagation from auth-db")
graph = GraphViewer(nodes, edges, "auth-db")

nodes = [nAuthDb, nAuthSvc, nSession, nApiGw, nAdmin, nReporting, nCheckout, nSearch, nNotif, nPayments, nFraud, nIndex]
nAuthDb = { id: "auth-db", label: "auth-db (Root Cause)", status: "fails" }
nAuthSvc = { id: "auth-service", label: "auth-service", status: "fails" }
nSession = { id: "session-cache", label: "session-cache", status: "fails" }
nApiGw = { id: "api-gateway", label: "api-gateway", status: "fails" }
nAdmin = { id: "admin-console", label: "admin-console", status: "fails" }
nReporting = { id: "reporting", label: "reporting", status: "fails" }
nCheckout = { id: "checkout", label: "checkout", status: "fails" }
nSearch = { id: "search", label: "search", status: "fails" }
nNotif = { id: "notifications", label: "notifications", status: "fails" }
nPayments = { id: "payments", label: "payments", status: "ok" }
nFraud = { id: "fraud-check", label: "fraud-check", status: "ok" }
nIndex = { id: "search-index", label: "search-index", status: "ok" }

edges = [e1, e2, e3, e4, e5, e6, e7, e8, e9, e10, e11, e12]
e1 = { from: "auth-service", to: "auth-db" }
e2 = { from: "session-cache", to: "auth-service" }
e3 = { from: "api-gateway", to: "auth-service" }
e4 = { from: "api-gateway", to: "session-cache" }
e5 = { from: "checkout", to: "api-gateway" }
e6 = { from: "checkout", to: "payments" }
e7 = { from: "payments", to: "fraud-check" }
e8 = { from: "search", to: "api-gateway" }
e9 = { from: "search", to: "search-index" }
e10 = { from: "admin-console", to: "auth-service" }
e11 = { from: "notifications", to: "checkout" }
e12 = { from: "reporting", to: "admin-console" }

stepsTitle = TextContent("Failure Timeline", "large-heavy")
cascadeSteps = Card([stepsList])
stepsList = Steps([step1, step2, step3, step4])
step1 = StepsItem("T+0: Database Offline", "auth-db goes down. auth-service immediately loses its primary datastore and fails.")
step2 = StepsItem("T+1: Core Gateways & Admin", "session-cache, api-gateway, and admin-console drop offline because they require auth-service to authenticate requests.")
step3 = StepsItem("T+2: Domain Services", "With the api-gateway and admin-console down, external routing to checkout, search, and reporting fails.")
step4 = StepsItem("T+3: Edge Consumers", "notifications fail because they rely on the upstream checkout events. (Note: payments, fraud-check, and search-index remain technically healthy, though unreachable).")
